  me.calc_loop_triangles();vertices=[(-float(v.co.y),float(v.co.x),float(v.co.z))for v in me.vertices]
  before=[(tuple(t.vertices),tuple(t.loops),t.material_index)for t in me.loop_triangles]
  normals=[(-float(n.vector.y),float(n.vector.x),float(n.vector.z))for n in me.corner_normals]
  assert len(normals)==len(me.loops)and normals
  slots=list(me.materials);face_materials=[f.material_index for f in me.polygons]
