  assert [tuple(v.co)for v in me.vertices]==vertices,'Signed permutation is exactly representable in raw float32'
  assert [(tuple(t.vertices),tuple(t.loops),t.material_index)for t in me.loop_triangles]==before
  assert list(me.materials)==slots and [f.material_index for f in me.polygons]==face_materials
  actual=[tuple(n.vector)for n in me.corner_normals];assert len(actual)==len(normals)
