  angles=[math.atan2(math.sqrt(sum(x*x for x in (a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]))),sum(x*y for x,y in zip(a,b)))for a,b in zip(actual,normals)]
