  records.append({'original_node':o.name,'vertices':len(vertices),'indexed_corners':len(normals),'triangles':len(before),'raw_corner_maximum_component_error_dimensionless':maximum,'raw_corner_maximum_angle_radians':max(angles),'export_codec_maximum_component_error_dimensionless':codec_error,'codec_tolerance_dimensionless':TOL,'raw_corner_comparison_is_diagnostic_only':True,'signed_permutation_determinant':1,'index_order_and_materials_unchanged':True})
